  {target:"Developing premises", c:"premise", sents:["Velo Bikes planned its new model for 2027.","The team expected fuel prices to rise and city traffic to get worse, which would increase demand for e-cycles.","The design was sporty.","It hired two new engineers."], a:1, why:"Assumptions about the future: <b>developing premises</b>."},
  {target:"Reduces risks of uncertainty", c:"imp", sents:["Harvest Foods buys wheat from farmers.","Its managers planned for a possible poor harvest by signing contracts with farmers in three different states.","The company sells biscuits.","Its logo is green."], a:1, why:"Preparing for possible change: <b>reduces risks of uncertainty</b>."},
  {target:"Leads to rigidity", c:"lim", sents:["Bloom Florists planned to sell roses all through February.","When a sudden flower-import ban hit, prices doubled.","The manager still refused to change the plan or switch to lilies, saying the plan was final.","Its shop is in Pune."], a:2, why:"Refusing to change the plan: <b>leads to rigidity</b>."}
